scan_linter_check.script:
(function(engine) {
    var rule = new global.EcsContext(engine.current).businessRule();
    if (!engine.rootNode || !rule) {
        return;
    }
    var hits = new global.EcsBusinessRule(new global.EcsAst(engine.rootNode), rule).recursiveUpdates();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-BR-002',
        title: 'Potential recursive Business Rule update',
        recommendation: 'Call setWorkflow(false) on the record before saving it when other Business Rules must not ' +
            'run, or add a condition that stops the rule from matching its own write. Review whether the rule\'s ' +
            'conditions already prevent it from triggering itself, and mute this finding with a reason if they do.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
